// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 100 ether); // >= MinSum so Collect is allowed

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0); // unlockTime = block.timestamp

        vm.warp(block.timestamp + 1); // unlock time has passed

        uint256 pre = actor.balance;
        vm.prank(actor);
        c.Collect(amount);

        // Rule: ether credited via Put is withdrawable via Collect.
        assertTrue(actor.balance - pre == amount);
    }
}
